def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 0 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        stack.append((ny,nx))
            components.append(cells)
    out = [row[:] for row in grid]
    if components:
        largest = max(components, key=len)
        smallest = min(components, key=len)
        for r, c in largest:
            out[r][c] = 8
        for r, c in smallest:
            out[r][c] = 7
    return out
